#!/usr/bin/env bash
# step200 — (1) upgrade order DELIVERY email (receipt + login credentials +
# "How to get started" instructions + View order / Invoice / WhatsApp buttons),
# (2) send ONE test to the given email for a random real product by creating a
# sample delivered order so all links work. Invoice URL derives from order URL.
set -uo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
TO="${1:-ishtiaqmails@gmail.com}"
cd "$GSZ" || { echo "FATAL: no $GSZ"; exit 1; }

cp -p lib/emails.js "lib/emails.js.bak-step200-$TS"
echo "backup: lib/emails.js.bak-step200-$TS"
restore(){ echo "!! restoring emails.js"; [ -f "lib/emails.js.bak-step200-$TS" ] && cp -p "lib/emails.js.bak-step200-$TS" lib/emails.js; }
trap 'restore' ERR

base64 -d > lib/emails.js <<'EEOF'

EEOF
node --check lib/emails.js || { echo 'EMAILS.JS SYNTAX FAIL'; restore; exit 2; }
grep -q 'How to get started' lib/emails.js || { echo 'VERIFY FAILED: instructions block missing'; restore; exit 3; }
echo "verify ok: premium delivery email written"

trap - ERR
pm2 restart gsz --update-env >/dev/null 2>&1 || pm2 restart gsz >/dev/null 2>&1
ok=0
for i in $(seq 1 25); do
  code=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
  if [ "$code" = "200" ]; then ok=1; echo "health ok (HTTP 200) after ${i} tries"; break; fi
  sleep 0.6
done
[ "$ok" = "1" ] || { echo "HEALTH CHECK FAILED (last: ${code:-none})"; exit 4; }

# --- send ONE test delivery email (creates a sample delivered order) ---
SJS=$(mktemp /tmp/send200.XXXXXX.js)
base64 -d > "$SJS" <<'SEOF'

SEOF
node "$SJS" "$TO"
echo "STEP200 DONE."
